P('/general-contractor/', hero="re-direttore-lavori",
 title="General contractor in Veneto and Friuli, Italy | One contract",
 desc="General contractor for homeowners, businesses, hotels and investors in Veneto and Friuli: design, permits, trades, supplies and site under one contract, fixed price and firm deadlines.",
 ogtitle="General contractor in Italy — Danova Real Estate", ogdesc="One contract and one manager for design, trades, supplies and site in north-east Italy.",
 crumbs=[RE, ("General contractor", None)], eyebrow="General contractor · Veneto & Friuli",
 h1=f"General contractor: {G}one contract, one responsibility.{_G}",
 lead="For those investing in a property, opening premises or renewing a hotel, the general contractor is the single counterpart who coordinates designers, builders, installers and suppliers and is accountable for timing, cost and quality. Danova Real Estate does this in Veneto and Friuli, with a fixed price and the schedule in the contract.",
 cta1="Let’s discuss the project", cta2="What a general contractor does",
 sezioni=[
  {"id": "in-breve", "tipo": "breve", "eyebrow": "In short", "h2": f"What is {G}a general contractor{_G}",
   "testo": "A <b>general contractor</b> is the company that takes responsibility for the entire building project towards the client: it signs <b>one contract</b>, coordinates design, permits, specialist trades and supplies and guarantees <b>price and deadlines</b>. The client does not have to manage dozens of suppliers: there is <b>one point of contact</b>. Danova Real Estate acts as general contractor for homeowners, businesses, hotels and property investors in Veneto and Friuli Venezia Giulia, Italy.",
   "fatti": [("Clients", "Homeowners, businesses, hotels, investors"), ("Contract", "Single, fixed price"), ("Deadlines", "Binding schedule"),
             ("Coordination", "Designers, trades, suppliers"), ("Reporting", "Weekly progress"), ("Area", "Veneto and Friuli Venezia Giulia")]},
  {"id": "cosa", "tipo": "cards", "eyebrow": "What we do", "h2": f"From feasibility {G}to handover{_G}",
   "corpo": [("Feasibility study", "Planning check, property condition, cost and time estimate before purchase or investment."),
             ("Design and renders", "Architectural and interior design with 3D renders, together with the appointed technicians."),
             ("Permits", "Building permits, fire safety, site safety and notices to authorities."),
             ("Selection and coordination", "Building crews, installers, window makers and furnishers: selected, contracted and coordinated by us."),
             ("Cost and quality control", "Budget under control, checks during works, variations only if approved in writing."),
             ("Handover and documentation", "Inspections, certificates, as-built drawings and manuals: everything to use and maintain the property.")]},
  {"id": "split", "tipo": "split", "img": "re-direttore-lavori", "didascalia": "One manager for the whole site",
   "eyebrow": "The advantage", "h2": f"Why it beats {G}separate contracts{_G}",
   "corpo": ["With separate contracts the client signs many agreements and becomes, in effect, the site coordinator: matching timings, interfaces between companies and responsibilities. Every delay by one crew affects the others and it is often unclear who should pay for it.",
             "With a general contractor all these interfaces are our problem. The price is set beforehand, there is one calendar and responsibilities do not bounce around: if something goes wrong you know exactly whom to turn to.",
             "It is the right formula for " + A('/ristrutturazione-hotel/', 'hotels') + ", " + A('/ristrutturazione-negozi-uffici-ristoranti/', 'shops, offices and restaurants') + ", income properties and complete renovations of high-end homes."]},
  {"id": "per-chi", "tipo": "cards", "eyebrow": "Who it’s for", "h2": f"Who relies {G}on a general contractor{_G}",
   "corpo": [("Property investors", "Purchase, renovation and letting with certain budget and timing: short lets, splits, resale."),
             ("Businesses", "New premises, offices, showrooms and stores delivered ready to use."),
             ("Hotels and hospitality", "Low-season projects with contract furniture included."),
             ("Homeowners", "Major renovations of villas, farmhouses and premium apartments."),
             ("Foreign owners", "We follow the site on your behalf and report in English or Romanian."),
             ("Chains and franchises", "Replicable openings to the same standard in several towns.")]},
  {"id": "promesse", "tipo": "promesse", "eyebrow": "Guarantees", "h2": f"What you find {G}in our contract{_G}"},
  {"id": "come", "tipo": "passi", "eyebrow": "The method", "h2": f"How we run {G}a project{_G}",
   "corpo": [("Brief and survey", "Objectives, budget, constraints and desired handover date."), ("Feasibility and estimate", "Technical and planning checks, first estimate of cost and time."),
             ("Design and fixed price", "Design, renders, specifications, lump-sum offer and schedule."), ("Execution", "Coordination of trades and supplies, weekly reporting with photos and progress."),
             ("Handover", "Inspections, documentation and post-handover support.")]}],
 faqtitle=f"Questions about {G}general contracting.{_G}",
 faq=[("What is the difference between a general contractor and a builder?", "A builder carries out the works within its trade; a general contractor takes responsibility for the entire project, including work entrusted to other specialist companies, and answers to the client with a single contract."),
      ("Is a general contractor more expensive?", "Coordination has a value, but it is usually recovered by avoiding delays, overlaps between trades and unplanned variations. Above all, the price is set in advance: you know what you will spend."),
      ("Do you work with my designers?", "Yes. We can develop the design ourselves or work with your architect or engineer, handling execution, supplies and coordination."),
      ("Do you work for investors who do not live in Italy?", "Yes: we manage site, suppliers and permits locally and report with photos and video calls in English or Romanian.")] + FAQ_BASE[:3],
 ctabox={"h2": "A project to entrust to a single manager?", "p": "Tell us about the property, the goal and the timing: we reply with a first feasibility assessment.", "btn": "Let’s discuss the project"},
 altrititle="Related pages",
 altri=[("General contractor in Treviso", u('/general-contractor-treviso/')), ("General contractor in Venice", u('/general-contractor-venezia/')), ("General contractor in Padua", u('/general-contractor-padova/')),
        ("General contractor in Verona", u('/general-contractor-verona/')), ("Turnkey hotel", u('/hotel-chiavi-in-mano/')), ("Turnkey renovation", u('/ristrutturazioni-chiavi-in-mano/')), ("For architects", u('/impresa-edile-per-architetti/'))],
 svc=svc("General contractor", "General contracting",
         "General contracting in Veneto and Friuli, Italy, for homeowners, businesses, hotels and investors: feasibility study, design and renders, permits, selection and coordination of trades and supplies, cost and quality control, handover with full documentation, single fixed-price contract.",
         ["Feasibility study", "Design and renders", "Permits", "Trade coordination", "Cost and quality control", "Handover and documentation"]))

